package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamTheoryColorBank3 {
    private const val T = "චිත්‍ර කලා මූලිකාංග, නිර්මාණ මූලධර්ම හා වර්ණ න්‍යාය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("චිත්‍ර කලාවේ සියලුම දෘශ්‍ය මූලිකාංගවල ආරම්භක ඒකකය ලෙස සැලකෙන 'ලක්ෂ්‍යය' (Point / Dot) චලනය වීමෙන් කුමක් සෑදේද?", "රේඛාවක් (Line)", "තානයක් (Tone)", "වර්ණ චක්‍රයක් (Color Wheel)", "රන් අනුපාතයක් (Golden Ratio)", "චලනය වන ලක්ෂ්‍යයක ගමන් මග රේඛාව ලෙස අර්ථ දැක්වෙන අතර රේඛා එක්වීමෙන් හැඩතල බිහිවේ."),
        q("චිත්‍රයක පුද්ගලයෙකු බලන දිශාව හෝ ඇඟිල්ල දිගු කරන දිශාව ඔස්සේ නරඹන්නාගේ ඇස යොමු වන නොපෙනෙන රේඛාව හඳුන්වන්නේ කෙසේද?", "ව්‍යංග්‍ය රේඛාව (Implied Line)", "සමෝච්ඡ රේඛාව (Contour Line)", "කඩඉරි රේඛාව (Broken Line)", "තිරස් අක්ෂ රේඛාව (Horizon Line)", "සැබෑ ලෙස ඇඳ නොතිබුණද දෘෂ්ටි සම්බන්ධතාව හරහා සංයුතිය ගලපන රේඛාව ව්‍යංග්‍ය රේඛාවයි."),
        q("රේඛා චිත්‍රයක ආලෝකය වැටෙන පැත්ත සිහින්වත් අඳුරු හෝ බර පැත්ත ඝනවත් ඇඳීමේ ශිල්ප ක්‍රමය හඳුන්වන්නේ කුමන නමින්ද?", "රේඛා බර වෙනස් කිරීම (Line Weight)", "වර්ණ විභේදනය (Divisionism)", "අභිනය සටහන (Gesture Sketch)", "ද්විමාන ඡායාරූපකරණය (Silhouette)", "රේඛාවේ මහත හා සිහින් බව වෙනස් කිරීමෙන් වර්ණ හෝ සෙවණැලි නොමැතිව පවා ත්‍රිමාණ බර මතු කළ හැකිය."),
        q("පෙරදිග පින්සල් චිත්‍රවල මෙන් තුනී සිට ඝන දක්වා නිදහසේ ගලා යන හැඟීම්බර රේඛා විලාසය කෙසේ හැඳින්වේද?", "අක්ෂර කලාත්මක රේඛාව (Calligraphic Line)", "යාන්ත්‍රික රේඛාව (Mechanical Line)", "ජ්‍යාමිතික රේඛාව (Geometric Line)", "බිඳුණු රේඛාව (Dashed Line)", "පින්සලේ පීඩනය අනුව වෙනස් වන මෙම රේඛා රිද්මය හා චලනය ප්‍රකාශ කිරීමට ඉතා සුදුසුය."),
        q("ඝනකය, ගෝලය, කේතුව සහ සිලින්ඩරය වැනි නිශ්චිත ගණිතමය පරිමාවන් සහිත ත්‍රිමාණ ආකෘති වර්ග කෙරෙන්නේ කෙසේද?", "ජ්‍යාමිතික ආකෘති (Geometric Forms)", "ඓන්ද්‍රීය හැඩතල (Organic Shapes)", "ද්විමාන රූප (Flat Shapes)", "සෘණ අවකාශ (Negative Spaces)", "සොබාදහමේ ගල් හා වලාකුළු වැනි අවිධිමත් ඓන්ද්‍රීය ආකෘතිවලට වෙනස්ව මේවා නියමිත මිනුම් සහිතය."),
        q("පැතලි කැන්වසයක් මත වර්ණ හා සෙවණැලි යොදා දැව කොටයක් හෝ ලෝම මතුපිටක් ලෙස ඇසට පෙනෙන සේ මවන වයනය කුමක්ද?", "දෘශ්‍ය හෙවත් අනුකරණ වයනය (Visual Texture)", "සැබෑ හෙවත් ස්පර්ශ වයනය (Actual Texture)", "ද්‍රව්‍යමය වයනය (Tactile Texture)", "ඝන කැටයම් වයනය (Carved Texture)", "අතින් ඇල්ලූ විට කඩදාසිය සිනිඳු වුවද ඇසට රළු බවක් පෙනීම දෘශ්‍ය වයනයේ විශේෂත්වයයි."),
        q("රළු බිත්තියක්, කාසියක් හෝ ගස් පොත්තක් මත කඩදාසියක් තබා පැන්සලකින් හෝ පැස්ටල් කූරකින් ඇතිල්ලීමෙන් වයනය ලබා ගැනීමේ ක්‍රමය කුමක්ද?", "ෆ්‍රොටාජ් ක්‍රමය (Frottage)", "ග්‍රැෆිටෝ ක්‍රමය (Sgraffito)", "මොසැයික් ක්‍රමය (Mosaic)", "ටෙසලේෂන් ක්‍රමය (Tessellation)", "ප්‍රකෘති පෘෂ්ඨ රටා කඩදාසියට පිටපත් කර ගැනීමට මෙම සරල මුද්‍රණ හා වයන ශිල්පය යොදා ගැනේ."),
        q("තීන්ත තලය මත තවත් තීන්ත හෝ මැටි තැවරූ පසු කූරකින් හෝ පිහි තුඩකින් සූරා යට ස්තරය මතු කිරීමේ ක්‍රමය කුමක්ද?", "ස්ග්‍රැෆිටෝ ක්‍රමය (Sgraffito)", "වොෂ් ක්‍රමය (Watercolor Wash)", "ස්ටිප්ලින් ක්‍රමය (Stippling)", "ස්මජිං ක්‍රමය (Smudging)", "මැටි බඳුන් අලංකරණයේදී මෙන්ම පැස්ටල් හා ඇක්‍රිලික් චිත්‍රවල වයන මැවීමටද මෙය භාවිත වේ."),
        q("භූ දර්ශන සිතුවමක ගැඹුර හා අවකාශය ගොඩනැගීම සඳහා පිහිටුවන ප්‍රධාන දෘශ්‍ය තල තුන මොනවාද?", "පෙරබිම, මැදබිම හා පසුබිම", "වම, දකුණ හා මැද තීරුව", "උඩුමහල, බිම්මහල හා පියස්ස", "ප්‍රාථමික, ද්විතීයික හා තෘතීයික", "නරඹන්නාට ළඟම වස්තු පෙරබිමේත්, ප්‍රධාන සිදුවීම් මැදබිමේත්, ඈත කඳු හා අහස පසුබිමේත් ස්ථානගත කෙරේ."),
        q("එක් වස්තුවක් තවත් වස්තුවක කොටසක් වසාගෙන ඉදිරියෙන් පිහිටීම මගින් ගැඹුර හැඟවීමේ අවකාශ උපක්‍රමය කුමක්ද?", "එකිනෙක වැසී යාම (Overlapping)", "ප්‍රමාණ සමාන වීම (Equal Sizing)", "වර්ණ ප්‍රතිවිරෝධය (Color Clash)", "මධ්‍ය සමමිතිය (Radial Symmetry)", "ඉදිරියෙන් ඇති වස්තුව සම්පූර්ණයෙන් පෙනෙන අතර පසුපස වස්තුව අර්ධ ලෙස වැසීමෙන් පැහැදිලි දුර පරතරයක් මැවේ."),
        q("චිත්‍රයක දුර පවතින වස්තූන් ළඟ ඇති වස්තූන්ට වඩා කුඩාවට ඇඳීම මගින් ගොඩනැගෙන්නේ කුමන මූලිකාංගයද?", "අවකාශ ගැඹුර (Illusion of Space)", "සැබෑ වයනය (Actual Texture)", "ද්විමාන රටාව (Flat Pattern)", "වර්ණ උෂ්ණත්වය (Color Temperature)", "සමාන ප්‍රමාණයේ ගස් හෝ කණු පෙළක් දුර යන විට ක්‍රමයෙන් කුඩා වී පෙනීම දෘෂ්ටි ස්වභාවයයි."),
        q("පසුබිමට යන වස්තූන් චිත්‍ර තලයේ පහළ දාරයට වඩා ඉහළ කොටසින් හෝ ක්ෂිතිජ රේඛාවට ආසන්නව ඇඳීමෙන් පෙන්වන්නේ කුමක්ද?", "දුරස්ථ බව (Distance in Space)", "වස්තුවේ බර වැඩි බව (Heavy Weight)", "රාත්‍රී අඳුරු කාලය (Night Time)", "තද රළු මතුපිට (Rough Texture)", "සාමාන්‍යයෙන් පහළ දාරය අසල වස්තු ළඟ ලෙසත් ඉහළට වන්නට ඇඳි වස්තු ඈත ලෙසත් ඇසට දැනේ."),
        q("ආලෝක ප්‍රභවයකට නිරාවරණය වූ වස්තුවක් මගින් මේසය හෝ බිම මත ඇති කරන අඳුරු පැල්ලම හඳුන්වන්නේ කෙසේද?", "පතිත සෙවණැල්ල (Cast Shadow)", "ආලෝක ලපය (Highlight)", "පරාවර්තන ආලෝකය (Reflected Light)", "මධ්‍යම තානය (Mid-tone)", "වස්තුව අසලම පතිත සෙවණැල්ල ඉතා තදට පිහිටන අතර දුර යන විට එහි දාර ක්‍රමයෙන් මෘදු වේ."),
        q("ගෝලාකාර වස්තුවක දීප්තිමත් ආලෝක කොටස හා තද අඳුරු හර සෙවණැල්ල අතර පිහිටන ස්වාභාවික වර්ණ ප්‍රදේශය කුමක්ද?", "මධ්‍යම තානය (Half-tone / Mid-tone)", "පතිත සෙවණැල්ල (Cast Shadow)", "විශේෂ ආලෝක ලපය (Specular Highlight)", "අවර්ණ පසුබිම (Neutral Backdrop)", "වස්තුවේ සැබෑ මතුපිට වර්ණය හා පරිමාණ හැඩය වඩාත් පැහැදිලිව හඳුනාගත හැක්කේ මධ්‍යම තාන කලාපයේදීය."),
        q("ත්‍රිමාණ වස්තුවක ආලෝකය වැටෙන පැත්ත අවසන් වී සෙවණැලි ප්‍රදේශය ආරම්භ වන සීමා කලාපය හඳුන්වන්නේ කෙසේද?", "ආලෝක-අඳුරු සීමාව (Terminator / Core)", "ක්ෂිතිජ රේඛාව (Horizon Line)", "අතුරුදන් ලක්ෂ්‍යය (Vanishing Point)", "මධ්‍ය අක්ෂය (Central Axis)", "වස්තුවේ පරිමාව වක්‍ර වන ආකාරය මෙම සීමා කලාපයේ මෘදු හෝ තියුණු බව අනුව තීරණය වේ."),
        q("රෙම්බ්‍රාන්ඩ් හා කරවැජියෝ මෙන් අඳුරු පසුබිමක් මත තද ආලෝක-අඳුරු ප්‍රතිවිරෝධතාවකින් රූප නාට්‍යමය ලෙස මතු කිරීම කුමක්ද?", "චියාරෝස්කියුරෝ හා ටෙනෙබ්‍රිසම්", "පොයින්ටිලිසම් හා ඔප් ආර්ට්", "ෆෝවිසම් හා කියුබිසම්", "මිනිමලිසම් හා ඩාඩා", "අඳුර හා ආලෝකය අතර උපරිම තාන වෙනස යොදා ගැනීමෙන් චිත්‍රයට ගැඹුරු ත්‍රිමාණ නාට්‍යමය බවක් ලැබේ."),
        q("තීන්ත හා වර්ණක (Pigments) මිශ්‍ර කිරීමේදී මූලික වර්ණ සියල්ල එකට මිශ්‍ර කළහොත් අඳුරු දුඹුරු හෝ කළු පැහැයක් ලැබෙන ක්‍රමය කුමක්ද?", "ව්‍යාකලන වර්ණ මිශ්‍රණය (Subtractive Mixing)", "ආකලන ආලෝක මිශ්‍රණය (Additive Mixing)", "දෘශ්‍ය තිත් මිශ්‍රණය (Optical Mixing)", "අර්ධ විනිවිද පෙනෙන ඡායා (Glazing)", "වර්ණක ආලෝක තරංග උරාගන්නා බැවින් සාම්ප්‍රදායික RYB හා මුද්‍රණ CMYK ක්‍රම ව්‍යාකලන ක්‍රම වේ."),
        q("වර්ණ චක්‍රය තුළ එකිනෙකට ප්‍රතිවිරුද්ධ අනුපූරක වර්ණ යුගල දෙකක් (සෘජුකෝණාස්‍රයක් ආකාරයෙන්) තෝරා ගැනීමේ ක්‍රමය කුමක්ද?", "චතුර්වර්ණ සංයෝජනය (Tetradic Scheme)", "ඒකවර්ණ සංයෝජනය (Monochromatic Scheme)", "සමීප වර්ණ සංයෝජනය (Analogous Scheme)", "උදාසීන සංයෝජනය (Neutral Scheme)", "වර්ණ හතරක් අඩංගු මෙම සංයෝජනයේදී එක් වර්ණයක් ප්‍රමුඛ කර අනෙක් වර්ණ අඩුවෙන් යෙදීම සුදුසුය."),
        q("වර්ණ චක්‍රයේ සමාන දුරකින් අංශක 90 බැගින් පිහිටි වර්ණ හතරක් යොදාගන්නා වර්ණ සැලැස්ම හඳුන්වන්නේ කෙසේද?", "සමචතුරස්‍ර වර්ණ සංයෝජනය (Square Scheme)", "ත්‍රිකෝණ වර්ණ සංයෝජනය (Triadic Scheme)", "ද්වි-අනුපූරක සංයෝජනය (Split Complementary)", "ප්‍රාථමික සංයෝජනය (Primary Scheme)", "මෙම වර්ණ හතරෙන් දෙකක් උණුසුම් හා දෙකක් සිසිල් වන බැවින් සමබර වර්ණ විවිධත්වයක් සපයයි."),
        q("ස්වාභාවික මැටි හා ඛනිජ වර්ගවලින් සැකසෙන රතු ඕකර්, කහ ඕකර්, බර්න්ට් සියෙනා සහ රෝ අම්බර් හඳුන්වන්නේ කුමන නමින්ද?", "පාංශු වර්ණ (Earth Tones)", "නියොන් වර්ණ (Fluorescent Colors)", "පැස්ටල් වර්ණ (Pastel Tints)", "ආකලන ප්‍රාථමික (RGB Colors)", "භූ දර්ශන, මිනිස් සම හා සාම්ප්‍රදායික ගැමි සිතුවම් සඳහා මෙම ස්වාභාවික වර්ණ ඉතා උචිතය."),
        q("නිවැරදි කළු තීන්ත නොමැති විට චිත්‍ර ශිල්පීන් අල්ට්‍රාමැරින් නිල් සහ බර්න්ට් අම්බර් දුඹුරු මිශ්‍ර කර සාදාගන්නා ගැඹුරු කළු පැහැය කුමක්ද?", "වර්ණ මිශ්‍ර කළු (Chromatic Black)", "ශුද්ධ කාබන් කළු (Ivory Black)", "අවර්ණ සුදු තානය (Pure White)", "උදාසීන කහ (Muted Yellow)", "නළයෙන් ගන්නා කළු තීන්තවලට වඩා වර්ණ මිශ්‍ර කළු සෙවණැලිවලට ස්වාභාවික ගැඹුරක් හා ජීවයක් දෙයි."),
        q("ඉතා දීප්තිමත් වර්ණයක තීව්‍රතාව හෙවත් සැර ගතිය මෘදු කිරීම සඳහා කළු වෙනුවට එයට මිශ්‍ර කළ යුතු වඩාත් උචිත වර්ණය කුමක්ද?", "එම වර්ණයේ අනුපූරක වර්ණය", "තද සුදු පැහැති වර්ණය", "දීප්තිමත් ෆ්ලෝරසන්ට් කහ", "සමාන ප්‍රාථමික වර්ණයම", "උදාහරණයක් ලෙස දීප්තිමත් රතු පැහැය මෘදු කිරීමට කොළ ස්වල්පයක් එක් කිරීමෙන් ස්වාභාවික මිශ්‍රණයක් ලැබේ."),
        q("කලාවේදී 'වර්ණ ගැටුම' (Color Discord) යනුවෙන් අදහස් කරන දෘශ්‍යමය තත්ත්වය කුමක්ද?", "එකිනෙකට නොගැළපෙන සේ පෙනෙන වර්ණ සිතාමතා එක් කිරීම", "සියලුම වර්ණ සුදු පැහැයෙන් වැසී යාම", "තනි වර්ණයක එළි-අඳුරු පමණක් භාවිත කිරීම", "වර්ණ චක්‍රයේ පළමු වර්ණ තුන ඉවත් කිරීම", "නූතන ප්‍රකාශනවාදී හා පෝස්ටර් නිර්මාණවලදී නරඹන්නා තුළ කැළඹීමක් හෝ අවධානයක් මැවීමට මෙය යොදා ගැනේ."),
        q("වර්ණ චක්‍රයක එක් ප්‍රධාන පසුබිම් වර්ණයක් වෙනස් කිරීමෙන් මුළු මෝස්තර රටාවේම සමස්ත පෙනුම වෙනස් වී පෙනීමේ සංසිද්ධිය කුමක්ද?", "බෙසෝල්ඩ් ආචරණය (Bezold Effect)", "ස්ෆුමාටෝ ආචරණය (Sfumato Effect)", "ඩොප්ලර් ආචරණය (Doppler Effect)", "ට්‍රොම්ප් ලොයිල් (Trompe l'oeil)", "විල්හෙල්ම් වොන් බෙසෝල්ඩ් සොයාගත් මෙම රීතිය රෙදිපිළි හා පලස් මෝස්තර නිර්මාණයේදී ඉතා වැදගත් වේ."),
        q("වස්තුවක සැබෑ පවතින වර්ණය වෙනුවට චිත්තවේගීය හැඟීම් ප්‍රකාශ කිරීමට කලාකරුවා ස්වාධීනව යොදන වර්ණ හඳුන්වන්නේ කෙසේද?", "ප්‍රකාශන හෙවත් මනෝමය වර්ණ (Arbitrary Color)", "ස්ථානීය වර්ණ (Local Color)", "ඡායාරූපමය වර්ණ (Photographic Color)", "ඒකවර්ණ තානය (Achromatic Tone)", "නිල් පැහැති අශ්වයෙකු හෝ රතු ගසක් ඇඳීම මනෝමය වර්ණ භාවිතයට උදාහරණයකි."),
        q("දෘෂ්ටි ස්වභාවය අනුව ඉදිරියට නෙරා එන සේ පෙනෙන 'ඉදිරිගාමී වර්ණ' සහ ඈතට යන සේ පෙනෙන 'පසුගාමී වර්ණ' පිළිවෙළින් මොනවාද?", "උණුසුම් වර්ණ සහ සිසිල් වර්ණ", "සුදු වර්ණ සහ කහ වර්ණ", "අළු වර්ණ සහ කළු වර්ණ", "තද දම් සහ දීප්තිමත් රතු", "රතු හා තැඹිලි ඉදිරියට පනින ගුණයක්ද, නිල් හා කොළ පසුබිමට විහිදෙන ගුණයක්ද පෙන්වයි."),
        q("වර්ණ සංකේතවාදයේදී 'දම්' (Purple / Violet) වර්ණය බහුලව භාවිත කරන්නේ කුමන අදහසක් ප්‍රකාශ කිරීමටද?", "රාජකීයත්වය, අභිරහස හා අධ්‍යාත්මික බව", "අනතුරු ඇඟවීම හා රථවාහන තදබදය", "වනාන්තර සංරක්ෂණය හා ගොවිතැන", "දැඩි ශෝකය හා මරණීය බිය", "පැරණි කාලයේ දම් සායම් සෑදීම ඉතා මිල අධික වූ බැවින් එය රාජකීය හා ගෞරවනීය වර්ණයක් විය."),
        q("කහ (Yellow) වර්ණය මාර්ග සංඥා, කැබ් රථ හා පාසල් බස් රථ සඳහා යොදා ගැනීමට ප්‍රධාන හේතුව කුමක්ද?", "දුර සිට පවා ඇසට වේගයෙන් හා පැහැදිලිව පෙනීම", "සෑම දේශගුණයකදීම කිසිදා අවපැහැ නොවීම", "සායම් නිෂ්පාදන වියදම සම්පූර්ණයෙන් නොමැති වීම", "රාත්‍රී අඳුරේදී කළු පැහැයෙන් වැසී යාම", "දෘශ්‍ය වර්ණාවලියේ ඉහළම දීප්ති පරාවර්තනයක් ඇති කහ වර්ණය ක්ෂණික අවධානය දිනා ගනී."),
        q("බටහිර සංස්කෘතියේදී 'සුදු' පැහැය ප්‍රධානව මංගල හා පාරිශුද්ධත්ව සංකේතයක් වන අතර ඇතැම් පෙරදිග රටවල එය කුමක් සංකේතවත් කරයිද?", "ශෝකය, නිහඬ බව හා අවමංගල්‍ය අවස්ථා", "සටන්කාමී යුදමය ආක්‍රමණ", "කෘෂිකාර්මික අස්වනු නෙළීම", "වෙළඳ ප්‍රචාරණ ප්‍රවර්ධනය", "ශ්‍රී ලංකාව ඇතුළු ආසියානු සමාජවල සුදු වත පාරිශුද්ධත්වය මෙන්ම ශෝකජනක චාම් බවද දක්වයි."),
        q("පෝස්ටර් හා වෙළෙඳ සන්නාම නිර්මාණයේදී 'කළු' වර්ණය ප්‍රධානව භාවිත කිරීමෙන් ලබා දෙන හැඟීම කුමක්ද?", "ගාම්භීර බව, බලය හා සුඛෝපභෝගී අලංකාරය", "ළමා සෙල්ලක්කාර සැහැල්ලුව", "හරිත පරිසර හිතකාමී බව", "උදෑසන සූර්යාලෝකයේ ප්‍රබෝධය", "රන් හෝ රිදී සමඟ කළු වර්ණය යෙදීමෙන් ඉහළ තත්ත්වයේ සන්නාම පෙනුමක් ගොඩනගා ගත හැකිය."),
        q("දුඹුරු (Brown) වර්ණය සිතුවමක හෝ නිර්මාණයක බහුලව යෙදීමෙන් පරිසරයට ගෙන එන මනෝභාවය කුමක්ද?", "ස්ථාවර බව, ස්වාභාවික දැව හා පොළොවේ උණුසුම", "අධික සීතල හිම කඳු පරිසරය", "විද්‍යුත් තාක්ෂණික වේගවත් බව", "මුහුදු රළ අතර කලබලකාරී බව", "සත්ව ලෝම, ගස් කඳන් හා පැරණි ලී ගෘහ භාණ්ඩ හරහා දුඹුරු වර්ණය ආරක්ෂිත හා විශ්වසනීය හැඟීමක් දෙයි."),
        q("රතු වර්ණයට සුදු මිශ්‍ර කිරීමෙන් ලැබෙන 'රෝස' (Pink) පැහැයෙන් සාමාන්‍යයෙන් ප්‍රකාශ වන්නේ කුමක්ද?", "මෘදු බව, කරුණාව හා සෙනෙහස", "දැඩි කෝපය හා යුද භීතිය", "පැරණි ගල් කුළුණුවල බරපතළ බව", "රාත්‍රී අහසේ ගැඹුරු හිස් බව", "රතු පැහැයේ තීව්‍ර උණුසුම අඩු වී මෘදු භාවයක් ලැබීම නිසා මෙය සෞම්‍ය හැඟීම් පෙන්වයි."),
        q("සාම්ප්‍රදායික ශ්‍රී ලාංකික බිතුසිතුවම් ශිල්පීන් දීප්තිමත් සුදු පැහැය සකසා ගැනීමට භාවිත කළ ස්වාභාවික ද්‍රව්‍යය කුමක්ද?", "මකුළු මැටි (Kaolin white clay)", "පිළිස්සූ ගල් අඟුරු කුඩු", "කොස් ගෙඩිවල ලාටු", "සාදිලිංගම් රතු කුඩු", "සෝදා පිරිසිදු කර ගත් සුදු මකුළු මැටි හුණු බදාම පසුබිමට හා සුදු වර්ණ ගැන්වීමට යොදා ගැනිණි."),
        q("පැරණි ලාංකේය සිත්තරුන් කහ වර්ණය නිපදවා ගැනීම සඳහා ගොකටු ගසේ කිරි සමඟ එක්ව යොදාගත් ඛනිජ වර්ණය කුමක්ද?", "හිරියල් (Orpiment)", "නිල් අවරිය (Indigo)", "පහන් දැලි (Lamp soot)", "ගුරුගල් (Red ochre)", "ගොකටු කිරි හා හිරියල් කුඩු ඇඹරීමෙන් ඉතා කල්පවතින දීප්තිමත් කහ වර්ණක සැකසිණි."),
        q("සම්ප්‍රදායික විහාර චිත්‍රවල බාහිර රේඛා ඇඳීමට අවශ්‍ය කළු වර්ණය පැරණි ශිල්පීන් සාදා ගත්තේ කෙසේද?", "පහන් දැලි හෝ කොහොල්ලෑ දුම එකතු කිරීමෙන්", "මකුළු මැටි ජලයේ දිය කිරීමෙන්", "සාදිලිංගම් කැට කුඩු කිරීමෙන්", "ගොකටු කිරි අව්වේ වේලීමෙන්", "කැකුණ තෙල් හෝ රෙදි පුලුස්සා එකතු කරගත් සියුම් කළු දැලි දිවුල් ලාටු සමඟ මිශ්‍ර කෙරිණි."),
        q("මහනුවර යුගයේ සිතුවම්වල බහුල පසුබිම් රතු පැහැය සෑදීමට භාවිත කළ ඛනිජ ද්‍රව්‍ය යුගලය කුමක්ද?", "ගුරුගල් හා සාදිලිංගම් (Cinnabar)", "හිරියල් හා මකුළු මැටි", "දොරණ තෙල් හා හුණු කුඩු", "නිල් අවරිය හා අළු කුඩු", "තද ගඩොල් රතු පසුබිම මත රූප කැපී පෙනීම සඳහා ගුරුගල් හා සාදිලිංගම් වර්ණ යොදා ගැනුණි."),
        q("පැරණි දේශීය චිත්‍ර කලාවේ භාවිත කළ ස්වාභාවික නිල් වර්ණය නිස්සාරණය කර ගත්තේ කුමන ශාකයෙන්ද?", "නිල් අවරිය ශාකය (Indigo)", "කොස් ශාකයේ ලී කුඩු", "පොල් කටු අඟුරු කුඩු", "සියඹලා ඇට කුඩු", "රෙදිපිළි මෙන්ම සිතුවම් සඳහාද නිල් අවරිය පත්‍ර පැසවා සාදන නිල් සායම් භාවිත කළහ."),
        q("සාම්ප්‍රදායික ශ්‍රී ලාංකික වර්ණක කුඩු බිත්තියට හොඳින් ඇලවීම සඳහා බන්ධකයක් (Binder) ලෙස මිශ්‍ර කළේ කුමක්ද?", "දිවුල් ලාටු හා දොරණ තෙල්", "සින්තටික් ඉපොක්සි මැලියම්", "පෙට්‍රල් හා භූමිතෙල්", "කැල්සියම් ක්ලෝරයිඩ් ද්‍රාවණ", "දිවුල් ලාටු වර්ණක සඳහාත් දොරණ තෙල් ආරක්ෂිත ඔප දැමීමේ ආලේපනයක් ලෙසත් භාවිත විය."),
        q("වර්ණ න්‍යායේදී 'ඒකවර්ණ' (Monochromatic) සහ 'අවර්ණ' (Achromatic) සංයෝජන අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "ඒකවර්ණයේ මූලික පැහැයක් ඇති අතර අවර්ණයේ කළු-සුදු-අළු පමණි", "අවර්ණයේ ප්‍රාථමික වර්ණ තුනම අඩංගු වීම", "ඒකවර්ණයේ අනුපූරක වර්ණ දෙකක් පැවතීම", "අවර්ණයේ දීප්තිමත් රතු පැහැය පමණක් තිබීම", "සුදු, කළු හා අළු පමණක් භාවිත කිරීම අවර්ණ (Achromatic) වන අතර එක් පැහැයක එළි-අඳුරු ප්‍රභේද ඒකවර්ණ වේ."),
        q("සොබාදහමේ ගොළුබෙලි කටු හා පුරාණ ග්‍රීක දෙවොල් සැලසුම්වල දැකිය හැකි ඉතා සමබර 'රන් අනුපාතය' (Golden Ratio) අගය කුමක්ද?", "1 : 1.618 පමණ", "1 : 10.50 පමණ", "1 : 0.250 පමණ", "1 : 5.000 පමණ", "මෙම ගණිතමය අනුපාතය මත පදනම් වූ සර්පිලාකාර සංයුතිය නරඹන්නාට ඉතා ප්‍රසන්න දෘශ්‍ය සමබරතාවක් දෙයි."),
        q("චිත්‍රයක මාර්ගයක්, ගංගාවක් හෝ වැටක් යොදාගෙන නරඹන්නාගේ දෙනෙත් ක්‍රමයෙන් ප්‍රධාන වස්තුව වෙත ගෙන යාමේ උපක්‍රමය කුමක්ද?", "මඟ පෙන්වන රේඛා (Leading Lines)", "මධ්‍ය සමමිතිය (Radial Symmetry)", "ඒකවර්ණ තානය (Monochrome)", "පාරාන්ධ ආවරණය (Opaque Layer)", "සංයුතියේ පෙරබිමෙන් ආරම්භ වී නාභිගත ස්ථානය වෙත ඇදෙන රේඛා ප්‍රේක්ෂක අවධානය පාලනය කරයි."),
        q("භූ දර්ශන සිතුවමක සන්සුන්, අලංකාර ගලා යාමක් ඇති කිරීම සඳහා ගංගාවක් හෝ මාවතක් වක්‍ර කර ඇඳීමේ සංයුති ක්‍රමය කුමක්ද?", "S-වක්‍ර සංයුතිය (S-Curve Composition)", "සෘජු කතිර සංයුතිය (Cross Composition)", "හතරැස් කොටු රටාව (Grid Pattern)", "සිරස් තීරු රටාව (Vertical Stripes)", "S-හැඩති වක්‍රය ඇස සුමට ලෙස සිතුවම පුරා ගෙන යාමට උපකාරී වන සම්භාව්‍ය සංයුති ක්‍රමයකි."),
        q("පුනරුද යුගයේ ආගමික චිත්‍රවල මරියතුමිය හා රූප පෙළ ගැස්වීමේදී ශක්තිමත් ස්ථාවර බවක් දීමට බහුලව යොදාගත් සංයුතිය කුමක්ද?", "ත්‍රිකෝණාකාර සංයුතිය (Triangular Composition)", "විසිරුණු තිත් සංයුතිය (Random Dots)", "අසමමිතික චංචල රේඛා (Zigzag Lines)", "ප්‍රතිලෝම රේඛා ජාලය (Inverted Grid)", "පුළුල් පාදමක් හා ඉහළ මුදුනක් සහිත පිරමීඩාකාර පිහිටීම සිතුවමට ගාම්භීර ස්ථිර බවක් ගෙන දෙයි."),
        q("සිතුවමක එක් පසෙක උස ගසක් හෝ ගොඩනැගිල්ලක් සහ පහළින් තිරස් වෙරළක් තැබීමෙන් සෑදෙන අසමමිතික සංයුති ආකාරය කුමක්ද?", "L-හැඩැති සංයුතිය (L-Shaped Composition)", "O-හැඩැති වෘත්ත සංයුතිය", "X-හැඩැති කතිර සංයුතිය", "Z-හැඩැති අකුණු සංයුතිය", "L-හැඩය මගින් සිතුවමේ අනෙක් පස ඇති නිදහස් සෘණ අවකාශය කැපී පෙනෙන ලෙස රාමු කරයි."),
        q("මෝස්තර රටාවක කවයක් සහ ත්‍රිකෝණයක් මාරුවෙන් මාරුවට (A-B-A-B) නැවත නැවත යෙදීමෙන් නිර්මාණය වන රිද්ම වර්ගය කුමක්ද?", "මාරුවෙන් මාරුවට යෙදෙන රිද්මය (Alternating Rhythm)", "අහඹු විසිරුණු රිද්මය (Random Rhythm)", "ඒකාකාරී සම රිද්මය (Monotonous Rhythm)", "නිශ්චල මධ්‍ය අක්ෂය (Static Axis)", "අංග දෙකක් හෝ වර්ණ දෙකක් නියමිත රටාවකට මාරු වීමෙන් ඇසට ප්‍රසන්න චලන හැඟීමක් ඇති වේ."),
        q("කුඩා වෘත්තයක සිට ක්‍රමයෙන් මධ්‍යම හා විශාල වෘත්ත දක්වා පිළිවෙළට ප්‍රමාණය වෙනස් කරමින් සාදන රිද්මය කෙසේ හැඳින්වේද?", "ප්‍රගතිශීලී රිද්මය (Progressive Rhythm)", "සමමිතික ප්‍රතිබිම්බය (Mirror Symmetry)", "වියුක්ත ගැටුම (Abstract Discord)", "පැතලි සමතුලිතතාව (Flat Balance)", "ප්‍රමාණය, වර්ණය හෝ පරතරය එක් අන්තයක සිට අනෙක් අන්තයට ක්‍රමානුකූලව වැඩි හෝ අඩු වීම මෙහි ලක්ෂණයයි."),
        q("නිශ්චිත නාභිගත මධ්‍යස්ථානයක් නොමැතිව මුළු මතුපිට පුරාම සමාන බරකින් රටා හෝ වර්ණ විසුරුවා හරින සමතුලිතතාව කුමක්ද?", "සමස්ත තල සමතුලිතතාව (All-over / Crystallographic Balance)", "ඒකපාර්ශ්වික සමතුලිතතාව (One-sided Balance)", "ද්විපාර්ශ්වික කැඩපත් සමමිතිය", "මධ්‍ය කේන්ද්‍රීය වෘත්ත සමමිතිය", "ඇඳුම් රෙදි මෝස්තර, බිතුපත් හා ජැක්සන් පොලොක්ගේ සිතුවම් මෙම සමතුලිතතාවට නිදසුන් වේ."),
        q("කලා නිර්මාණයේදී 'පරිමාණය' (Scale) සහ 'සමානුපාතය' (Proportion) අතර ඇති මූලික වෙනස කුමක්ද?", "පරිමාණය සමස්ත ප්‍රමාණය වන අතර සමානුපාතය කොටස් අතර අනුපාතයයි", "පරිමාණය වර්ණ ගැන වන අතර සමානුපාතය රේඛා ගැන පමණි", "පරිමාණය ත්‍රිමාණ මූර්තිවලට පමණක් සීමා වූවකි", "සමානුපාතය යනු කඩදාසියේ වර්ණය මැනීමේ ක්‍රමයයි", "මිනිස් අතක් හිසට සාපේක්ෂව ඇති ප්‍රමාණය සමානුපාතය වන අතර ප්‍රතිමාව අඩි 20ක් උස වීම පරිමාණයයි."),
        q("පුරාණ මිසර හා මධ්‍යකාලීන චිත්‍රවල ප්‍රධාන රජු හෝ ශාන්තුවරයා අනෙක් මිනිසුන්ට වඩා විශාලව ඇඳීමේ රීතිය කුමක්ද?", "ධූරාවලි පරිමාණය (Hierarchical Scale)", "රේඛීය දෘෂ්ටිකෝණය (Linear Perspective)", "වායව දෘෂ්ටිකෝණය (Aerial Perspective)", "කෙටි පෙනුම (Foreshortening)", "සැබෑ දුර ප්‍රමාණයට නොව සමාජීය හෝ ආගමික වැදගත්කම අනුව රූප විශාල කර දැක්වීම මෙම ක්‍රමයයි."),
        q("මෝස්තර 'රටාවක්' (Pattern) සහ 'වයනයක්' (Texture) අතර ඇති ප්‍රධානතම වෙනස කුමක්ද?", "රටාව සැලසුම් කළ නැවත යෙදීමක් වන අතර වයනය මතුපිට ස්වභාවයයි", "රටාව හැමවිටම කළු-සුදු පමණක් වන අතර වයනය රතු පමණි", "වයනය කඩදාසි මත පමණක් දැකිය හැකි මෝස්තරයකි", "රටාව මූර්ති කලාවේ කිසි විටෙකත් භාවිත නොවේ", "එකම මෝස්තර ඒකකය ක්‍රමවත්ව නැවත යෙදීමෙන් රටාවක් සෑදෙන අතර ස්පර්ශ හෝ දෘශ්‍ය රළු-සිනිඳු බව වයනයයි."),
        q("නිර්මාණයක සෘණ අවකාශය මැද සිර වී කැපී යන සුදු පැහැ හිස් ඉඩකඩ (Trapped Negative Space) නිර්මාණයේදී වළක්වන්නේ ඇයි?", "නිදහස් අවකාශ ගලා යාම හා සංයුති එකමුතු බව බිඳෙන නිසා", "කඩදාසියේ සුදු පැහැය ඉක්මනින් දුර්වර්ණ වන නිසා", "අතිරේක පැන්සල් හා තීන්ත වැඩිපුර වැය වන නිසා", "වස්තූන් සියල්ල වෘත්තාකාර හැඩයට හැරෙන නිසා", "වස්තූන් වටා ඇති සෘණ අවකාශය පිටත දාර සමඟ සම්බන්ධ වී නිදහසේ ගලා යාම සංයුතිය සාර්ථක කරයි."),
        q("සිතුවමක සියලු අංග කැබලි වී නොගොස් එකම භාෂාවකින් කතා කරන බව හැඟවීම සඳහා එක් වර්ණයක් තැන් කිහිපයක යෙදීම කුමක්ද?", "වර්ණ පුනරාවර්තනය හෙවත් වර්ණ දෝංකාරය (Color Echo)", "වර්ණ විරෝධතා ගැටුම (Color Clash)", "ද්විමාන ඡායාරූපකරණය (Silhouette)", "ස්ග්‍රැෆිටෝ සීරීම් ක්‍රමය (Sgraffito)", "උදාහරණයක් ලෙස අහසේ ඇති නිල් පැහැයෙන් ස්වල්පයක් පෙරබිමේ ජලයේ හෝ ඇඳුමක යෙදීමෙන් ඒකාබද්ධතාව වැඩි වේ.")
    )
}
